if (!window.ShihikoCollectionNavigation) {
	class ShihikoCollectionNavigation {
		constructor() {
			this.requestController = null;
			this.navigationId = 0;
			this.sectionOrder = new Map([
				['collection_hero', 0],
				['collection_story_cta_bTzknC', 1],
				['template-collection', 2]
			]);
			this.currentTemplateSuffix = document.querySelector('shihiko-header[data-header-new]')?.dataset.templateSuffix || '';
			document.body.dataset.shihikoTemplateSuffix = this.currentTemplateSuffix;

			document.addEventListener('click', (event) => this.onClick(event), { capture: true });
			window.addEventListener('popstate', (event) => this.onPopState(event));
		}

		isCollectionPage() {
			return document.body.classList.contains('template-name-collection') && Boolean(document.querySelector('.collection-catalog'));
		}

		isCollectionUrl(url) {
			return url.origin === window.location.origin && /^\/collections(?:\/|$)/.test(url.pathname);
		}

		withPreviewTheme(url) {
			const previewThemeId = new URL(window.location.href).searchParams.get('preview_theme_id');
			if (previewThemeId) url.searchParams.set('preview_theme_id', previewThemeId);
			return url;
		}

		shouldHandleClick(event, link) {
			return Boolean(
				link &&
				event.button === 0 &&
				!event.metaKey &&
				!event.ctrlKey &&
				!event.shiftKey &&
				!event.altKey &&
				!link.target &&
				!link.hasAttribute('download')
			);
		}

		onClick(event) {
			if (!this.isCollectionPage()) return;

			const target = event.target;
			const link = target instanceof Element ? target.closest('[data-collection-navigation-link]') : null;
			if (!this.shouldHandleClick(event, link)) return;

			const url = this.withPreviewTheme(new URL(link.href, window.location.origin));
			if (!this.isCollectionUrl(url) || url.href === window.location.href) return;

			event.preventDefault();
			event.stopPropagation();
			this.rememberCurrentHistoryEntry();
			this.load(url, { updateHistory: true, restoreScroll: 0 }).catch((error) => {
				if (error.name !== 'AbortError') window.location.assign(url.href);
			});
		}

		onPopState(event) {
			const url = new URL(window.location.href);
			if (!this.isCollectionPage() || !this.isCollectionUrl(url)) {
				window.location.reload();
				return;
			}

			this.load(url, { restoreScroll: event.state?.scrollY || 0 }).catch((error) => {
				if (error.name !== 'AbortError') window.location.reload();
			});
		}

		rememberCurrentHistoryEntry() {
			window.history.replaceState(
				{
					...(window.history.state || {}),
					shihikoCollectionNavigation: true,
					scrollY: window.scrollY
				},
				document.title,
				window.location.href
			);
		}

		getSectionId(element) {
			return element?.closest('.shopify-section')?.id.replace(/^shopify-section-/, '') || null;
		}

		getSectionPrefix(sectionId) {
			const separatorIndex = sectionId?.lastIndexOf('__');
			return separatorIndex > -1 ? sectionId.slice(0, separatorIndex) : null;
		}

		getSectionIds() {
			const headerId = this.getSectionId(document.querySelector('shihiko-header[data-header-new]'));
			const templateId = this.getSectionId(document.querySelector('.collection-catalog'));
			const templatePrefix = this.getSectionPrefix(templateId);

			if (!headerId || !templatePrefix) {
				throw new Error('Collection navigation sections are not available');
			}

			return {
				header: headerId,
				hero: `${templatePrefix}__collection_hero`,
				story: `${templatePrefix}__collection_story_cta_bTzknC`,
				template: templateId
			};
		}

		async load(url, { updateHistory = false, restoreScroll = 0 } = {}) {
			const navigationId = ++this.navigationId;
			this.requestController?.abort();
			this.requestController = new AbortController();
			const sectionIds = this.getSectionIds();
			const requestUrl = new URL(url.href);
			requestUrl.searchParams.set('sections', [sectionIds.header, sectionIds.hero, sectionIds.story, sectionIds.template].join(','));

			this.setLoadingState(true);
			document.body.classList.remove('disable-scroll');

			try {
				let sections;

				try {
					const response = await fetch(requestUrl.href, {
						headers: { Accept: 'application/json' },
						signal: this.requestController.signal
					});

					if (!response.ok) throw new Error(`Collection navigation failed with status ${response.status}`);

					sections = await response.json();
					if (!sections[sectionIds.header] || !sections[sectionIds.template]) {
						throw new Error('Collection navigation response is incomplete');
					}
				} catch (error) {
					if (error.name === 'AbortError') throw error;
					sections = await this.fetchDocumentSections(url, sectionIds);
				}

				this.replaceMainSections(sections, sectionIds);
				this.replaceHeader(sections[sectionIds.header], sectionIds.header);
				this.syncPageMetadata();
				this.refreshCollectionScripts();

				if (updateHistory) {
					window.history.pushState(
						{ shihikoCollectionNavigation: true, scrollY: 0 },
						document.title,
						url.href
					);
				}

				window.requestAnimationFrame(() => {
					window.scrollTo(0, restoreScroll);
					document.querySelector('.collection-menu__link--active')?.focus({ preventScroll: true });
				});
			} finally {
				if (navigationId === this.navigationId) {
					this.setLoadingState(false);
				}
			}
		}

		async fetchDocumentSections(url, sectionIds) {
			const response = await fetch(url.href, {
				headers: { Accept: 'text/html' },
				signal: this.requestController.signal
			});

			if (!response.ok) throw new Error(`Collection document request failed with status ${response.status}`);

			const html = await response.text();
			const documentFragment = new DOMParser().parseFromString(html, 'text/html');
			const getSectionMarkup = (selector) => documentFragment.querySelector(selector)?.closest('.shopify-section')?.outerHTML || null;

			const header = getSectionMarkup('shihiko-header[data-header-new]');
			const template = getSectionMarkup('.collection-catalog');
			if (!header || !template) throw new Error('Collection document is missing navigation sections');

			return {
				[sectionIds.header]: header,
				[sectionIds.hero]: getSectionMarkup('.collection-hero'),
				[sectionIds.story]: getSectionMarkup('.collection-story-cta'),
				[sectionIds.template]: template
			};
		}

		replaceMainSections(sections, sectionIds) {
			[
				{ id: sectionIds.hero, order: 0 },
				{ id: sectionIds.story, order: 1 },
				{ id: sectionIds.template, order: 2 }
			].forEach(({ id, order }) => this.replaceOrInsertSection(id, sections[id], order));
		}

		replaceOrInsertSection(sectionId, markup, order) {
			const currentSection = document.getElementById(`shopify-section-${sectionId}`);
			if (!markup) {
				currentSection?.remove();
				return;
			}

			const template = document.createElement('template');
			template.innerHTML = markup.trim();
			const incomingSection = template.content.firstElementChild;
			if (!incomingSection) return;

			if (currentSection) {
				currentSection.replaceWith(incomingSection);
				return;
			}

			const main = document.querySelector('main');
			if (!main) return;

			const sectionBefore = Array.from(main.children).find((section) => {
				const sectionKey = section.id.split('__').pop();
				return this.sectionOrder.has(sectionKey) && this.sectionOrder.get(sectionKey) > order;
			});

			main.insertBefore(incomingSection, sectionBefore || null);
		}

		replaceHeader(markup, sectionId) {
			const currentSection = document.getElementById(`shopify-section-${sectionId}`);
			if (!currentSection) return;

			const template = document.createElement('template');
			template.innerHTML = markup.trim();
			const incomingSection = template.content.firstElementChild;
			if (incomingSection) currentSection.replaceWith(incomingSection);
		}

		syncPageMetadata() {
			const header = document.querySelector('shihiko-header[data-header-new]');
			if (!header) return;

			const previousSuffix = document.body.dataset.shihikoTemplateSuffix || this.currentTemplateSuffix;
			if (previousSuffix) document.body.classList.remove(`template-${previousSuffix}`);

			const nextSuffix = header.dataset.templateSuffix;
			if (nextSuffix) document.body.classList.add(`template-${nextSuffix}`);
			this.currentTemplateSuffix = nextSuffix || '';
			document.body.dataset.shihikoTemplateSuffix = nextSuffix || '';
			document.body.classList.toggle('header-overlay-page', header.dataset.headerOverlay === 'true');

			if (header.dataset.pageTitle) document.title = header.dataset.pageTitle;

			const canonical = document.querySelector('link[rel="canonical"]');
			if (canonical && header.dataset.canonicalUrl) canonical.href = header.dataset.canonicalUrl;

			const description = document.querySelector('meta[name="description"]');
			if (description) description.content = header.dataset.pageDescription || '';
		}

		refreshCollectionScripts() {
			if (typeof window.reloadFilterEvents === 'function') {
				if (typeof window.TomSelect !== 'undefined') {
					window.reloadFilterEvents();
				} else {
					window.desktopSelectEvent?.();
					window.desktopCheckboxEvent?.();
				}
			}
			if (typeof window.reloadLazyLoad === 'function') window.reloadLazyLoad();
			if (typeof window.reloadProductCardHover === 'function') window.reloadProductCardHover();
			if (typeof window.setCollectionPreloaderSize === 'function') window.setCollectionPreloaderSize();
			if (window.CollectionDisplay) window.CollectionDisplay.refresh();
		}

		setLoadingState(isLoading) {
			document.querySelector('.loading-bar')?.classList.toggle('show', isLoading);
			document.querySelector('main')?.setAttribute('aria-busy', isLoading ? 'true' : 'false');
		}
	}

	window.ShihikoCollectionNavigation = new ShihikoCollectionNavigation();
}
